ucs.falcon_logscale_query:
#event_simpleName=ProcessRollup2
| ImageFileName=/(vssadmin|wmic|wbadmin|bcdedit|powershell|pwsh|cmd|sc|net|reg|wevtutil)\.exe$/i
| regex("(?i)(delete\\s+shadows|shadowcopy\\s+delete|delete\\s+catalog|Set-MpPreference.*Disable(Realtime|Behavior|IOAV|Script)|Add-MpPreference.*ExclusionPath|Uninstall-WindowsFeature.*Defender|DisableAntiSpyware|recoveryenabled\\s+No|bootstatuspolicy\\s+ignoreallfailures|stop\\s+WinDefend|config\\s+WinDefend.*disabled|config\\s+Sense.*disabled|wevtutil\\s+cl\\s|--password|--safe-mode|-no-vm-kill|-no-snap-kill)", field=CommandLine)
| case {
    regex("(?i)(delete\\s+shadows|shadowcopy\\s+delete|delete\\s+catalog)", field=CommandLine) | Phase := "shadow_wipe";
    regex("(?i)(Set-MpPreference|Add-MpPreference|Uninstall-WindowsFeature.*Defender|DisableAntiSpyware|WinDefend|Sense)", field=CommandLine) | Phase := "defender_disable";
    regex("(?i)(recoveryenabled|bootstatuspolicy)", field=CommandLine) | Phase := "recovery_disable";
    regex("(?i)wevtutil\\s+cl\\s", field=CommandLine) | Phase := "log_clear";
    regex("(?i)(--password|--safe-mode|-no-vm-kill|-no-snap-kill)", field=CommandLine) | Phase := "agenda_cli_flag";
    * | Phase := "other";
  }
| groupBy([aid, ComputerName, UserName], function=[count(field=Phase, distinct=true, as=distinct_phases), collect([Phase, CommandLine, ImageFileName, ParentBaseFileName])])
| distinct_phases >= 2
